head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";      // [부모 data] 업무처리번호 — 비어 있으면 신규 (AS-IS parentWin.scwin.clickBzProcsNo)
scwin.secugrpId = "";       // [부모 data] 증권그룹ID — 신규면 부모의 신규 유가증권 (AS-IS parentWin.cmb_NEW_SECUGRP_ID)
scwin.newMktTpCd = "";      // 신규 건 시장구분 기본값 — 유가·코스닥 사용자는 자기 시장, 그 밖은 "1" (원본 pJsMarket)
scwin.curDate = "";         // 서버 오늘(yyyyMMdd) — 상장일 비교 (원본 vCurDate)
scwin.isSaved = false;      // 저장·수정 성공 여부 — X 로 닫히면 부모가 isCloseButtonClick 으로 다시 조회한다
scwin.POPUP_URL_ISU = "/ui/lst/common/ULDSTF05012.xml";        // 종목 선택(공통)
scwin.POPUP_URL_CORP = "/ui/lst/lstmgt/ULDSTF41623.xml";       // 회사 선택(저장소에 전환본 없음 — §10)
scwin.POPUP_URL_INST = "/ui/lst/common/ULDSTF92011.xml";       // 기관 선택(공통)
scwin.POPUP_URL_PROD = "/ui/lst/pf/ULDSTF09320.xml";           // 상장형 수익증권 상품정보관리
scwin.POPUP_URL_DSCL = "/ui/listingcommon/ULDSTF92024.xml";    // 공시안내문작성(공통) — conversion-front 선례 경로
scwin.DSCL_FORM_CD = "68152H";      // 공시안내문 서식코드 — 유가(1)만 (AS-IS arr[0])
scwin.DISTR_MAX = 12;               // 분배기준일 최대 개수
// 원본 : /pf/ULDSTF09303.gfm (상장형 수익증권 신규상장관리 팝업) — W-Craft 1차 변환 + API 적용 개발 사본(ui/ULDSTF09303/ULDSTF09303.xml)
/*
 * 화면 동작
 *  - 부모(ULDSTF09302 신규상장)가 넘긴 업무처리번호가 있으면 기존 건, 없으면 신규다.
 *  - 신규: 종목 찾기(ULDSTF05012)로 종목을 고르면 종목정보를 받는다. 법인·종목정보와 LP회원·분배기준일을 넣고 [저장]하면
 *          업무처리번호를 새로 받아 등록하고, 그 번호로 다시 조회한다.
 *  - 기존: 업무처리번호로 조회한다. 상장일이 지나면 [안내문작성]만 켠다.
 *  - [상품정보관리] → ULDSTF09320, [안내문작성] → 공시안내문작성(ULDSTF92024).
 *  - 원본은 부모의 clickBzProcsNo·그리드·콤보를 직접 읽고 저장 뒤 부모 목록을 직접 갱신했다 — data 로 받고, 부모가 닫힌 뒤 다시 조회한다.
 *  - 통신은 화면에 적용된 API(경로·method·keyInfo)를 명세로 간주한다(사용자 결정 2026-10-29 준용).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09303/ULDSTF09303.md (§번호는 이 문서의 절)
 */

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09303.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 사용자 시장 → 공통 코드·LP 회원사 목록 → 파라미터 수신 → 달력 바인딩 → 기존 건 조회 또는 신규 준비.
 * 콤보·LP 목록을 먼저 받아야 조회 값이 표시되므로 await 한 뒤 조회한다. (원본 scwin.init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 사용자 시장 — 유가·코스닥이면 자기 시장, 그 밖은 유가(1) (원본 pJsMarket)
    const userMkt = String($c.session.getUserInfo("market") ?? "");
    scwin.newMktTpCd = (userMkt === "1" || userMkt === "2") ? userMkt : "1";
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 2) 공통 코드·LP 회원사 목록 (원본 fn_searchCode, fn_searchLPCode)
    await scwin.selectCode();
    await scwin.selectLpCode();

    // 3) 파라미터 수신 — 원본 parentWin.scwin.clickBzProcsNo·cmb_NEW_SECUGRP_ID (§1.2)
    const param = $c.data.getParameter() ?? {};
    scwin.vBzProcsNo = String(param.bzProcsNo ?? "");
    scwin.secugrpId = String(param.secugrpId ?? "");

    // 4) 달력 검사(규칙 37) — 단일 달력
    $c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ISU_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_EXP_DD, "yyyyMMdd");

    // 5) 기존 건 조회 / 신규 준비
    if (!$c.util.isEmpty(scwin.vBzProcsNo)) {
        await scwin.readSync();
        txb_SearchIsuCd.setValue(dma_isuItemRes.get("isuCd"));
        txb_SearchIsuNm.setValue(dma_isuItemRes.get("isuKorNm"));
        btn_sim.setDisabled(false);
    } else {
        cmb_SECUGRP_ID.setValue(scwin.secugrpId);                   // 부모의 신규 유가증권 (원본 parentWin.cmb_NEW_SECUGRP_ID)
        dma_isuItemRes.set("spotIsuTrdMktTpCd", scwin.newMktTpCd); // 사용자 시장
        await $c.lc.initLPGridData(dlt_grdLPList, "N");             // LP 입력 빈 행 15개
        btn_sim.setDisabled(true);    // 상품정보는 저장 뒤에 입력한다 (원본 jackal_11.08.08)
        scwin.applyLoadState();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
