/**
 * @method
 * @name scwin.selectCode
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공통 코드(명의개서대행기관·과세유형·복제유형)를 한 번에 받는다. 복제유형은 맨 앞에 빈 항목을 둔다. (원본 fn_searchCode — §5.1)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectCode = async function () {
    dma_codReq.set("codeList", "TRANSSTK_AGNT_CD, TAX_TP_CD, ETF_REPLICA_METHD_TP_CD");
    const sbmOptions = {
        id : "sbm_listCodeValue",
        method : "get",
        action : "/api/listing/common/code/list-code-value",
        ref : "dma_codReq",
        target : "dlt_transstkAgntCd=body.TRANSSTK_AGNT_CD,dlt_taxTpCd=body.TAX_TP_CD,dlt_etfReplicaMethdTpCd=body.ETF_REPLICA_METHD_TP_CD",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러

    dlt_etfReplicaMethdTpCd.insertRow(0);    // 복제유형 빈 항목(원본 그대로)
    return true;
};

/**
 * @method
 * @name scwin.selectLpCode
 * @author Inswave
 * @date 2026. 10. 30
 * @description LP 회원사 선택 목록을 받고 맨 앞에 빈 항목을 둔다. (원본 fn_searchLPCode — §5.2)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectLpCode = async function () {
    const sbmOptions = {
        id : "sbm_listLeadcomAll",
        method : "get",
        action : "/api/listing/common/code/list-leadcom-all",
        target : "dlt_LPList=body",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;

    dlt_LPList.insertRow(0);    // LP 빈 항목(원본 그대로)
    return true;
};

/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무처리번호로 신규상장 법인·종목정보를 조회한다. (원본 fn_read_sync 앞부분 — §5.3)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectOne = async function () {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/pf/new-listing/select-one",
        target : "dma_isuItemRes=body",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.vBzProcsNo });
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러
};

/**
 * @method
 * @name scwin.selectLpList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무처리번호의 LP 회원 목록을 조회한다. 화면에 적용된 API 는 ETF 신규상장 경로다(§5.4, §10 #5). (원본 fn_read_sync 뒷부분)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectLpList = async function () {
    dlt_grdLPList.removeAll();
    const sbmOptions = {
        id : "sbm_selectListLp",
        method : "get",
        action : "/api/listing/lstproc/etf/newlisting/management/select-list-lp",
        target : "dlt_grdLPList=body",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.vBzProcsNo });
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectIsuInfo
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 종목의 종목정보를 받는다. 응답에 시장구분이 비어 오면 사용자 시장으로 채운다. (원본 fn_getPfIsu_read_sync — §5.5, §8 #7)
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectIsuInfo = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectOneIsuInfo",
        method : "get",
        action : "/api/listing/lstproc/pf/new-listing/select-one-isu-info",
        target : "dma_isuItemRes=body",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;

    if ($c.util.isEmpty(dma_isuItemRes.get("spotIsuTrdMktTpCd"))) dma_isuItemRes.set("spotIsuTrdMktTpCd", scwin.newMktTpCd);
    scwin.applyLoadState();
    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규상장 등록(I)·수정(U) 전송 — 분배기준일 12칸·LP 저장 목록·증권그룹을 채워 법인·종목정보와 함께 보낸다. (원본 fn_trs — §5.6)
 * @param {String} trJob 처리구분 I: 등록, U: 수정
 * @param {String} bzProcsNo 업무처리번호 (등록이면 새로 받은 번호)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.saveTrs = async function (trJob, bzProcsNo) {
    scwin.setDistrBasMmDdToItem();
    scwin.buildLpSaveList(bzProcsNo);
    dma_isuItemRes.set("bzProcsNo", bzProcsNo);
    dma_isuItemRes.set("secugrpId", cmb_SECUGRP_ID.getValue());    // 원본 trs Parameters SECUGRP_ID
    dma_isuItemRes.set("lpInfoList", dlt_grdLPSaveList.getAllJSON());

    const sbmOptions = {
        id : "sbm_save",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/pf/new-listing/register" : "/api/listing/lstproc/pf/new-listing/modify",
        ref : "dma_isuItemRes",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    return await scwin.checkResult(result, (trJob === "I") ? "저장" : "수정");
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.readSync
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무처리번호로 다시 조회 — 법인·종목정보 → 버튼 상태·분배기준일 → LP 목록(빈 행 15개까지). (원본 fn_read_sync — §6.1)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.readSync = async function () {
    if (!await scwin.selectOne()) return false;
    scwin.applyLoadState();

    await scwin.selectLpList();
    await $c.lc.initLPGridData(dlt_grdLPList, "N");
    grd_LP.setScrollTop(0);
    return true;
};

/**
 * @method
 * @name scwin.applyLoadState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 뒤 화면 상태 — 신규면 저장 가능·종목 찾기 켬, 기존이면 종목 찾기 잠금·상장일 전이면 수정 가능(아니면 [안내문작성]만)·분배기준일 표시,
 * 상장번호가 있으면 [상장번호생성] 잠금, 편집할 수 있을 때만 분배기준일 추가·삭제. (원본 dts_IsuItem_OnLoadCompleted + fn_initForm + fn_disableDistrMmDd — §6.2)
 * @returns
 * @hidden N
 */
scwin.applyLoadState = function () {
    let editable = true;
    if ($c.util.isEmpty(scwin.vBzProcsNo)) {
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
        img_SearchIsu.setDisabled(false);
    } else {
        img_SearchIsu.setDisabled(true);
        if (edt_LIST_DD.getValue() > scwin.curDate) {
            $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
        } else {
            $c.util.setButtonState("grp_btnBox", { enable : ["guide"] }, scwin.BTN_MAP);
            editable = false;    // 원본: [저장]·[수정]이 모두 잠기면 분배기준일 추가·삭제도 잠근다
        }
        scwin.loadDistrBasMmDd();
    }

    if (!$c.util.isEmpty(txb_LIST_NO.getValue())) {
        img_LIST_NO.setDisabled(true);
    }
    img_Add.setDisabled(!editable);
    img_del.setDisabled(!editable);
};

/**
 * @method
 * @name scwin.loadDistrBasMmDd
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회한 수익분배기준월일 1~12 중 값이 있는 것을 분배기준일 그리드에 채우고 첫 값을 입력 칸에 보인다.
 * 원본은 빈 칸을 건너뛰면 행 번호가 어긋났다. (원본 fn_getDistrBasMmDd — §6.12, §8 #8)
 * @returns
 * @hidden N
 */
scwin.loadDistrBasMmDd = function () {
    const rows = [];
    for (let i = 1; i <= scwin.DISTR_MAX; i++) {
        const mmdd = String(dma_isuItemRes.get("earngDistrBasMmdd" + i) ?? "");
        if (mmdd !== "") rows.push({ earngDistrBasMmdd : mmdd });
    }
    dlt_distrBasMmDd.setJSON(rows);
    scwin.showDistrBasMmDd(0);
};

/**
 * @method
 * @name scwin.showDistrBasMmDd
 * @author Inswave
 * @date 2026. 10. 30
 * @description 분배기준일 그리드의 한 행 값을 입력 칸에 보인다. (원본 fn_DistrBasMmDdSetting — §6.12)
 * @param {Number} rowIndex 행 번호
 * @returns
 * @hidden N
 */
scwin.showDistrBasMmDd = function (rowIndex) {
    if (rowIndex >= 0 && rowIndex < dlt_distrBasMmDd.getRowCount()) {
        txb_DISTR_BAS_MMDD.setValue(dlt_distrBasMmDd.getCellData(rowIndex, "earngDistrBasMmdd"));
    }
};

/**
 * @method
 * @name scwin.checkDistrBasMmDd
 * @author Inswave
 * @date 2026. 10. 30
 * @description 분배기준일 입력 값 검사 — 4자리 MMDD, 월 1~12·일 1~31. (원본 fn_dateCheck — §6.12)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkDistrBasMmDd = async function () {
    const mmdd = String(txb_DISTR_BAS_MMDD.getValue() ?? "");
    const mm = Number.parseInt(mmdd.substring(0, 2), 10);
    const dd = Number.parseInt(mmdd.substring(2, 4), 10);
    if (mmdd.length !== 4 || !(mm >= 1 && mm <= 12) || !(dd >= 1 && dd <= 31)) {
        await $c.win.alert("올바른 [분배기준일]을 입력하세요.");
        txb_DISTR_BAS_MMDD.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.addDistrBasMmDd
 * @author Inswave
 * @date 2026. 10. 30
 * @description 분배기준일 추가 — 12개를 넘지 않고 값이 올바르면 그리드 끝에 더한다. (원본 fn_addDistrBasMmDd — §6.12)
 * @returns
 * @hidden N
 */
scwin.addDistrBasMmDd = async function () {
    if (dlt_distrBasMmDd.getRowCount() >= scwin.DISTR_MAX) {
        await $c.win.alert("[분배기준일]은  최대12개 입니다.");
        return;
    }
    if (!await scwin.checkDistrBasMmDd()) return;

    const rows = dlt_distrBasMmDd.getAllJSON();
    rows.push({ earngDistrBasMmdd : txb_DISTR_BAS_MMDD.getValue() });
    dlt_distrBasMmDd.setJSON(rows);
};

/**
 * @method
 * @name scwin.removeDistrBasMmDd
 * @author Inswave
 * @date 2026. 10. 30
 * @description 분배기준일 삭제 — 행이 있으면 확인 뒤 고른 행(없으면 첫 행)을 지우고 첫 값을 입력 칸에 보인다. (원본 img_del_onclick + fn_delDistrBasMmDd — §6.12)
 * @returns
 * @hidden N
 */
scwin.removeDistrBasMmDd = async function () {
    if (dlt_distrBasMmDd.getRowCount() === 0) {
        await $c.win.alert("삭제할 [분배기준일]이 없습니다.");
        return;
    }
    if (!await $c.win.confirm("'분배기준일'을 삭제하시겠습니까?")) return;

    const focused = grd_DISTR_BAS_MMDD.getFocusedRowIndex();
    dlt_distrBasMmDd.removeRow(focused >= 0 ? focused : 0);
    scwin.showDistrBasMmDd(0);
};

/**
 * @method
 * @name scwin.setDistrBasMmDdToItem
 * @author Inswave
 * @date 2026. 10. 30
 * @description 분배기준일 그리드를 수익분배기준월일 1~12 로 옮긴다(남는 칸은 빈 값). (원본 fn_SaveDistrBasMmDd — §6.12)
 * @returns
 * @hidden N
 */
scwin.setDistrBasMmDdToItem = function () {
    const rowCount = dlt_distrBasMmDd.getRowCount();
    dma_isuItemRes.setBroadcast(false);    // 반복 수정 중 화면 갱신 보류 (규칙 28)
    for (let i = 1; i <= scwin.DISTR_MAX; i++) {
        const mmdd = (i - 1 < rowCount) ? String(dlt_distrBasMmDd.getCellData(i - 1, "earngDistrBasMmdd") ?? "") : "";
        dma_isuItemRes.set("earngDistrBasMmdd" + i, mmdd);
    }
    dma_isuItemRes.setBroadcast(true, true);
};

/**
 * @method
 * @name scwin.buildLpSaveList
 * @author Inswave
 * @date 2026. 10. 30
 * @description LP 그리드에서 회원을 고른 행만 저장 목록으로 모은다. 원본은 빈 행을 건너뛰면 넣을 위치가 어긋났다. (원본 fn_setGridDataSet — §6.4, §8 #8)
 * @param {String} bzProcsNo 업무처리번호
 * @returns
 * @hidden N
 */
scwin.buildLpSaveList = function (bzProcsNo) {
    const rows = dlt_grdLPList.getAllJSON()
        .filter(row => String(row.lpMbrNo ?? "").trim() !== "")
        .map(row => ({ bzProcsNo : bzProcsNo, lpMbrNo : row.lpMbrNo, lpContrtDd : "", lpStrtDd : "" }));
    dlt_grdLPSaveList.setJSON(rows);
};

/**
 * @method
 * @name scwin.checkRequiredText
 * @author Inswave
 * @date 2026. 10. 30
 * @description 필수 문자 입력 — 비었으면 안내하고, 최대 byte(한글 2) 를 넘으면 공통 함수가 안내한다. (원본 fn_checkValueNullMaxlength — §6.3)
 * @param {Object} comp 입력 컴포넌트
 * @param {String} title 항목명
 * @param {Number} maxByte 최대 byte (화면 maxlength)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkRequiredText = async function (comp, title, maxByte) {
    if ($c.util.isEmpty(comp.getValue())) {
        await $c.win.alert(title + "을 입력하세요.");
        comp.focus();
        return false;
    }
    return $c.stf.checkMaxLength(comp, maxByte, title);
};

/**
 * @method
 * @name scwin.checkSymbolInput
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 전 영문 심볼 검사 — 비었으면 안내, 형식(영문·숫자·하이픈)이 틀리면 멈춤, 다른 회사·종목이 쓰는 심볼이면 중복 안내.
 * 원본은 중복 검사를 await 하지 않아 늘 통과했다. (원본 fn_CheckForm 유가 분기 — §6.3, §8 #5)
 * @param {Object} comp 심볼 입력 컴포넌트
 * @param {String} title 항목명(안내용)
 * @param {Boolean} isIsur 영문법인심볼이면 true, 영문종목심볼이면 false
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkSymbolInput = async function (comp, title, isIsur) {
    const symbl = String(comp.getValue() ?? "");
    if (symbl === "") {
        await $c.win.alert("[" + title + "]을 입력하세요.");
        comp.focus();
        return false;
    }
    if (!await $c.lc.engSymblCheck(symbl)) {
        comp.focus();
        return false;
    }
    // TODO: 영문종목심볼도 원본처럼 법인코드로 소유를 비교한다 — 서버 응답 cd 가 종목코드인지 확인 (§10 #6)
    const usable = isIsur
        ? await $c.lc.chkEtfCorpSymblDoubleInput(symbl, txb_ISUR_CD.getValue())
        : await $c.lc.chkIsuSymblDoubleInput(symbl, txb_ISUR_CD.getValue());
    if (!usable) {
        await $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 검사 — 시장·유가증권·종목·단축코드, (등록) 신규상장 중복, 법인·종목명 8종, (유가) 영문 심볼 2종, 우편번호·상장번호·전화번호,
 * 상장일(오늘 이후)·발행일, 집합투자업자·일반사무관리회사·신탁업자, LP 회원 1명 이상. 통과하면 PF 에 해당 없는 항목 고정값을 채운다. (원본 fn_CheckForm — §6.3)
 * @param {String} trJob 처리구분 I: 등록, U: 수정
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validate = async function (trJob) {
    if ($c.util.isEmpty(cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue())) {
        await $c.win.alert("[시장구분]을 선택하세요.");
        return false;
    }
    if ($c.util.isEmpty(cmb_SECUGRP_ID.getValue())) {
        await $c.win.alert("[유가증권]을 선택하세요.");
        return false;
    }
    if ($c.util.isEmpty(txb_ISU_CD.getValue())) {
        await $c.win.alert("[종목]을 선택하세요.");
        img_SearchIsu.focus();
        return false;
    }
    if ($c.util.isEmpty(txb_ISU_SRT_CD.getValue())) {
        await $c.win.alert("[종목단축코드]항목값이  없습니다.");
        txb_ISU_SRT_CD.focus();
        return false;
    }
    // TODO: 공통 중복 검사는 주식 신규상장 경로에 isurCd 키로 종목코드를 보낸다(원본 그대로) — 확인 필요 (§10 #4)
    if (trJob === "I" && await $c.lc.checkDoubleInput(txb_ISU_CD.getValue())) return false;

    const names = [
        [txb_COM_NM, "한글법인명", 80], [txb_COM_ABBRV, "한글법인약명", 40],
        [txb_COM_ENG_NM, "영문법인명", 80], [txb_COM_ENG_ABBRV, "영문법인약명", 40],
        [txb_ISU_KOR_NM, "한글종목명", 80], [txb_ISU_KOR_ABBRV, "한글종목약명", 40],
        [txb_ISU_ENG_NM, "영문종목명", 80], [txb_ISU_ENG_ABBRV, "영문종목약명", 40]
    ];
    for (const [comp, title, maxByte] of names) {
        if (!await scwin.checkRequiredText(comp, title, maxByte)) return false;
    }

    // 유가증권시장은 영문 심볼 필수 + 중복 검사
    if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "1") {
        if (!await scwin.checkSymbolInput(txb_ISUR_SYMBL, "영문법인심볼", true)) return false;
        if (!await scwin.checkSymbolInput(txb_ISU_ENG_SYMBL, "영문종목심볼", false)) return false;
    }

    const required = [
        [txb_ZIPCD, "[우편번호]를 선택하세요.", img_ZIPCD],
        [txb_LIST_NO, "[상장번호]를 선택하세요.", txb_LIST_NO],
        [txb_CORP_TEL_NO, "[법인전화번호]을 입력하세요.", txb_CORP_TEL_NO],
        [edt_LIST_DD, "[상장일]을 입력하세요.", edt_LIST_DD]
    ];
    for (const [comp, msg, focusComp] of required) {
        if ($c.util.isEmpty(comp.getValue())) {
            await $c.win.alert(msg);
            focusComp.focus();
            return false;
        }
    }
    if (scwin.curDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }

    const required2 = [
        [edt_ISU_DD, "[발행일(설정일)]을 입력하세요."],
        [txb_TRST_COM_NM, "[집합투자업자]을 선택하세요."],
        [txb_BZ_ADM_COM_NM, "[일반사무관리회사]을 입력하세요."],
        [txb_TRST_INST_NM, "[신탁업자(신탁회사)]을 입력하세요."]
    ];
    for (const [comp, msg] of required2) {
        if ($c.util.isEmpty(comp.getValue())) {
            await $c.win.alert(msg);
            comp.focus();
            return false;
        }
    }
    if ($c.lc.checkGridDataSet(dlt_grdLPList, "lpMbrNo")) {
        await $c.win.alert("[LP회원명을]을 선택하세요.");
        return false;
    }

    // PF 종목에는 해당되지 않는 항목 — 고정값 (원본 fn_CheckForm 끝)
    dma_isuItemRes.set("ceoNm", "-");
    dma_isuItemRes.set("stdIndCd", "-");
    dma_isuItemRes.set("listMethdTpCd", $c.lc.getGlbValue("LIST_METHD_TP_CD_4"));
    dma_isuItemRes.set("isuRsnContn", "신규상장");
    dma_isuItemRes.set("remk", "");
    return true;
};

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 10. 30
 * @description 처리 결과 판정 — 통신 성공이고 completeYn 이 false 가 아니면 성공. register·modify 는 응답 정의가 없어 completeYn 이 없으면 success 만 본다. (§5.6)
 * @param {Object} result executeDynamic 결과
 * @param {String} jobNm 처리명
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.checkResult = async function (result, jobNm) {
    // TODO: 등록·수정 응답 구조 확인 필요 — completeYn 유무 (§10 #2)
    const completeYn = result.responseJSON?.body?.completeYn;
    const completed = (completeYn === undefined || completeYn === null || String(completeYn) === "true" || completeYn === "Y");
    if (result.responseJSON?.success === true && completed) return true;

    await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
    return false;
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내고,
 * body 가 문자열이면 그대로, 객체면 bzProcsNo 를 문자열로 만든다. 14자리 검사는 호출부(scwin.save)가 한다. (원본 fn_save — §6.5)
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 채번 응답 모양·경로 미확정 — 공통 채번이 주식 변경상장 경로(stock/chglisting/new-bzprocsno)다 (§10 #3)
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    return String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록(I)·수정(U) — 검사 → 확인 → (등록) 채번 → 전송 → 안내 → 다시 조회. 등록이 성공한 뒤에만 업무처리번호를 반영하고 [상품정보관리]를 켠다.
 * 원본은 저장 뒤 부모 목록을 직접 갱신하고 부모 그리드 포커스를 옮겼다 — 부모가 닫힌 뒤 다시 조회한다. (원본 fn_save·fn_update·trs_Save_OnSuccess — §6.5)
 * @param {String} trJob 처리구분 I: 등록, U: 수정
 * @returns
 * @hidden N
 */
scwin.save = async function (trJob) {
    if (!await scwin.validate(trJob)) return;

    // "[저장]/[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(trJob)) return;

    let bzProcsNo = scwin.vBzProcsNo;
    if (trJob === "I") {
        bzProcsNo = await scwin.getNewBzProcsNo();
        if (bzProcsNo.length !== 14) {
            // MSG-0010 "업무처리번호생성실패"
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
            return;
        }
    }

    if (!await scwin.saveTrs(trJob, bzProcsNo)) return;

    scwin.vBzProcsNo = bzProcsNo;
    scwin.isSaved = true;
    await $c.win.alert($c.stf.getMessageParam("MSG-A001", (trJob === "I") ? "저장" : "수정"));

    await scwin.readSync();
    btn_sim.setDisabled($c.util.isEmpty(scwin.vBzProcsNo));    // 신규 저장되면 상품정보 입력 가능 (원본 jackal_11.08.08)
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 선택(ULDSTF05012)을 증권그룹·조회유형 SEC·시장구분으로 열고, 고르면 종목을 표시하고 분배기준일을 비운 뒤 종목정보를 받는다.
 * 취소·닫기면 아무것도 하지 않는다(개발 사본은 취소해도 분배기준일을 비웠다). (원본 img_SearchIsu_onclick + fn_SetParIsuCd — §6.6, 가이드 §6.5)
 * @returns
