        searchTyp : "SEC",      // 유가예비심사신규등록 (원본 SEARCH_TYP_SEC)
        mktTpCd : cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue()
    };
    const options = {
        id : "ULDSTF05012",
        popupName : "종목 선택",
        width : 600,
        height : 640,
        frameModal : "top",
        type : "pageFramePopup"
    };
