/**
 * @method
 * @name scwin.checkSymbolDup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 심볼 중복체크 버튼 — 비었으면 안내, 형식이 맞으면 중복 검사 결과(사용 가능·중복) 문구를 보인다. (원본 img_ISUR_SYMBL_onclick·img_ISU_ENG_SYMBL_onclick — §6.9)
 * @param {String} kind "isur" 영문법인심볼 | "isu" 영문종목심볼
 * @returns
 * @hidden N
 */
scwin.checkSymbolDup = async function (kind) {
    const isIsur = (kind === "isur");
    const comp = isIsur ? txb_ISUR_SYMBL : txb_ISU_ENG_SYMBL;
    const symbl = String(comp.getValue() ?? "");
    if (symbl === "") {
        await $c.win.alert(isIsur ? "[영문회사심볼]을 입력하세요." : "[영문종목심볼]을 입력하세요.");
        comp.focus();
        return;
    }
    if (!await $c.lc.engSymblCheck(symbl)) {
        comp.focus();
        return;
    }
    if (isIsur) {
        await $c.lc.chkEtfCorpSymblDoubleInput(symbl, txb_ISUR_CD.getValue());
    } else {
        await $c.lc.chkIsuSymblDoubleInput(symbl, txb_ISUR_CD.getValue());
    }
    const msg = $c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT");
    if (!$c.util.isEmpty(msg)) await $c.win.alert(msg);
};

