/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 임시 fn_GetPar 로 채우던 arr[0](유가만)·arr[1..3]·arr[5](유가만)와 마스터 데이터셋이다.
 * 마스터는 법인·종목정보에서 LP 목록(lpInfoList)을 뺀 것. (§6.14)
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function () {
    const mktId = String(dma_isuItemRes.get("spotIsuTrdMktTpCd") ?? "");
    const { lpInfoList, ...mst } = dma_isuItemRes.getJSON();
    return {
        formCd : (mktId === "1") ? scwin.DSCL_FORM_CD : "",                                         // AS-IS arr[0] — 코스닥은 없음
        bzProcsNo : String(dma_isuItemRes.get("bzProcsNo") ?? ""),                                // AS-IS arr[1]
        isurCd : String(dma_isuItemRes.get("isurCd") ?? ""),                                      // AS-IS arr[2]
        mktId : mktId,                                                                              // AS-IS arr[3]
        title : (mktId === "1") ? $c.lc.getDsclsTitle(txb_ISU_KOR_NM.getValue(), edt_LIST_DD.getValue()) : "",   // AS-IS arr[5] — 유가만
        mst : [mst]                                                                                 // AS-IS CopyDataSet(dts_IsuItem, param_dts_mst)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 30
 * @description 안내문작성 — 고친 내용이 있으면 수정 먼저 하라고 안내하고, 종목·저장 여부를 확인한 뒤 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다.
 * 개발 사본은 첫 줄 alert 뒤 return 으로 늘 막혀 있었다. 원본도 닫힌 뒤 다시 조회하지 않는다. (원본 fn_dscl — §6.14, §8 #1, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    if ($c.data.isModified(dma_isuItemRes)) {
        await $c.win.alert("수정된 내용이 있으니, 수정후  안내문 작성 버튼을 눌러주세요.");
        return;
    }
    if (!await scwin.checkBiz()) return;

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 793,
        height : 851,
        type : "pageFramePopup"
    };
    // TODO: 경로는 conversion-front 선례 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #8)
    await $c.win.openPopup(scwin.POPUP_URL_DSCL, options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 30
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. 원본 arr 길이를 그대로 재현한다 — 유가(1)는 [5] 까지 6,
 * 코스닥은 4(92024 는 arr 길이 5 이상이면 본문을 생성하지 않는다). (§6.14, §10 #8, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드(유가만) [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [5] 공시제목(유가만)
 * @param {Object} dltIsu 92024 의 종목 dataList (원본도 채우지 않음)
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    if (data.mktId === "1") {
        arr[5] = data.title;
    }

    scwin.fillDataList(dltMst, data.mst);
    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사 — §6.14)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
